function kFoldAccuracy(yTrue, yPred, k){ var n=yTrue.length; if(n<k||k<1) return null;
  var foldSize=Math.floor(n/k); var accs=[];
  for(var f=0;f<k;f++){ var s=f*foldSize, e=(f===k-1)?n:(f+1)*foldSize; var c=0,t=0;
    for(var i=s;i<e;i++){ t++; if(yTrue[i]===yPred[i]) c++; } accs.push(c/t); }
  var mean=accs.reduce(function(a,b){return a+b;},0)/accs.length;
  return {perFold:accs, mean:mean};
}
var EXPORTS={kFoldAccuracy:kFoldAccuracy};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
